import{_ as t,m as d,k as o,ah as c}from"./chunks/framework.HEc25T99.js";const p=JSON.parse('{"title":"API & Endpoints","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"fr/developers/development/api-endpoints.md","filePath":"src/fr/developers/development/api-endpoints.md"}'),i={name:"fr/developers/development/api-endpoints.md"};function s(a,e,n,r,l,u){return o(),d("div",null,[...e[0]||(e[0]=[c(`<h1 id="api-endpoints" tabindex="-1">API &amp; Endpoints <a class="header-anchor" href="#api-endpoints" aria-label="Permalink to &quot;API &amp; Endpoints&quot;">​</a></h1><p>Creopse expose une API REST complète sous <code>/api</code> — c&#39;est elle que consomme l&#39;interface d&#39;administration, mais aussi n&#39;importe quel client externe (application mobile, intégration tierce) qui voudrait diffuser le contenu ailleurs que via le frontend intégré.</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><h3 id="format-de-reponse" tabindex="-1">Format de réponse <a class="header-anchor" href="#format-de-reponse" aria-label="Permalink to &quot;Format de réponse&quot;">​</a></h3><p>Toutes les réponses suivent la même enveloppe JSON :</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Optionnel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;errorCode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Optionnel&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>data</code> contient le résultat (objet, tableau, ou objet paginé selon l&#39;endpoint) ; <code>message</code>/<code>errorCode</code> n&#39;apparaissent qu&#39;en cas de besoin (erreurs notamment).</p><h3 id="casse-des-cles" tabindex="-1">Casse des clés <a class="header-anchor" href="#casse-des-cles" aria-label="Permalink to &quot;Casse des clés&quot;">​</a></h3><p>Les clés JSON échangées avec le client sont en <strong>camelCase</strong>, converties automatiquement en snake_case côté serveur et inversement — envoyer et recevoir en camelCase, quelle que soit la convention utilisée en interne (base de données, code PHP).</p><h3 id="authentification" tabindex="-1">Authentification <a class="header-anchor" href="#authentification" aria-label="Permalink to &quot;Authentification&quot;">​</a></h3><p>Voir <a href="./authentication.html">Authentification</a> pour le détail. En résumé : <code>auth:sanctum</code> protège la plupart des routes d&#39;écriture et certaines routes de lecture, en acceptant indifféremment une session (interface d&#39;administration) ou un token Bearer (clients externes). Chaque groupe ci-dessous précise ce qui est public.</p><h3 id="limitation-de-requetes" tabindex="-1">Limitation de requêtes <a class="header-anchor" href="#limitation-de-requetes" aria-label="Permalink to &quot;Limitation de requêtes&quot;">​</a></h3><p>Toutes les routes sous <code>/api</code> sont soumises à une limite (<code>CREOPSE_RATE_LIMIT</code>, défaut <code>600</code>/minute), appliquée par IP ou par utilisateur authentifié selon <code>rate_limit_by</code> — voir <a href="./configuration.html#seuil-de-requetes">Configuration</a>.</p><h3 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h3><p>Les origines autorisées correspondent aux domaines listés dans <code>SANCTUM_STATEFUL_DOMAINS</code> (voir <a href="./authentication.html">Authentification</a>) — <code>https://</code> uniquement en production, <code>http://</code>/<code>https://</code> en développement. Les cookies (<code>supports_credentials</code>) sont supportés pour les requêtes de l&#39;interface d&#39;administration.</p><h2 id="contenu-pages-sections-menus-modeles-de-contenu-permaliens" tabindex="-1">Contenu (pages, sections, menus, modèles de contenu, permaliens) <a class="header-anchor" href="#contenu-pages-sections-menus-modeles-de-contenu-permaliens" aria-label="Permalink to &quot;Contenu (pages, sections, menus, modèles de contenu, permaliens)&quot;">​</a></h2><p>Le cœur de l&#39;API — consommé aussi bien par l&#39;interface d&#39;administration (écriture) que par les templates frontend (lecture).</p><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Accès</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/pages</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/pages/{page}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/pages</code>, <code>/pages/{page}</code></td><td>Authentifié</td></tr><tr><td><code>PUT</code></td><td><code>/pages/position</code></td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/sections</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/sections/{section}</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/section-data/{sectionSlug}/source/{pageSlug}/link/{linkId}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/sections</code>, <code>/sections/{section}</code></td><td>Authentifié</td></tr><tr><td><code>PUT</code></td><td><code>/sections/{section}/data-source-page</code>, <code>/sections/{section}/duplicate</code>, <code>/sections/{section}/copy-data</code></td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/sections/{slug}/link/{linkId}/page/{pageId}</code></td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/menus</code>, <code>/menus/{menu}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/menus</code>, <code>/menus/{menu}</code></td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/menu/items</code>, <code>/menu/items/{menuItem}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/menu/items</code>, <code>/menu/items/{menuItem}</code></td><td>Authentifié</td></tr><tr><td><code>PUT</code></td><td><code>/menu/items/position</code></td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/menu-settings</code>, <code>/menu-locations</code>, <code>/menu-item-groups</code>, <code>/menu-item-types</code> (+ <code>/{id}</code>)</td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td>mêmes ressources</td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/content-models</code>, <code>/content-models/{content_model}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/content-models</code>, <code>/content-models/{content_model}</code></td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/content-model/items</code>, <code>/content-model/items/{contentModelItem}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/content-model/items</code>, <code>/content-model/items/{contentModelItem}</code></td><td>Authentifié</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/content-model/user-items</code> (+ <code>/{id}</code>)</td><td>Public — soumission par un visiteur (formulaires)</td></tr><tr><td><code>POST</code></td><td><code>/content-model-items/list</code></td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/content-model-items/search/{query?}/{contentModelId?}</code></td><td>Authentifié</td></tr><tr><td><code>PUT</code></td><td><code>/content-model-items/related/{contentModelItem}</code></td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/permalinks</code>, <code>/permalinks/{permalink}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/permalinks</code>, <code>/permalinks/{permalink}</code></td><td>Authentifié</td></tr></tbody></table><h2 id="news" tabindex="-1">News <a class="header-anchor" href="#news" aria-label="Permalink to &quot;News&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Accès</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/news-articles</code>, <code>/news-articles/{newsArticle}</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/news-articles/headlines/{limit?}</code>, <code>/news-articles/random/{limit?}</code>, <code>/news-articles/categories</code>, <code>/news-articles/search/{query?}</code>, <code>/news-articles/list/months</code></td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/news-articles/list</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/news-articles</code>, <code>/news-articles/{newsArticle}</code> (+ <code>force</code>/<code>restore</code>)</td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/news-categories</code>, <code>/news-categories/{newsCategory}</code>, <code>/news-categories/articles</code> (+ <code>/{id}</code>)</td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/news-categories</code>, <code>/news-categories/{newsCategory}</code> (+ <code>position</code>, <code>force</code>, <code>restore</code>)</td><td>Authentifié</td></tr><tr><td><code>GET</code> <code>POST</code></td><td><code>/news-comments</code>, <code>/news-comments/{newsComment}</code></td><td>Public — y compris la création (<code>POST</code>)</td></tr><tr><td><code>PUT</code> <code>DELETE</code></td><td><code>/news-comments/{newsComment}</code> (+ <code>force</code>/<code>restore</code>)</td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/news-tags</code>, <code>/news-tags/{newsTag}</code>, <code>/news-tags/articles</code> (+ <code>/{id}</code>)</td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/news-tags</code>, <code>/news-tags/{newsTag}</code> (+ <code>force</code>/<code>restore</code>)</td><td>Authentifié</td></tr></tbody></table><h2 id="videos" tabindex="-1">Vidéos <a class="header-anchor" href="#videos" aria-label="Permalink to &quot;Vidéos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Accès</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/video-items</code>, <code>/video-items/{videoItem}</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/video-categories</code>, <code>/video-categories/{videoCategory}</code>, <code>/video-categories/items</code> (+ <code>/{id}</code>)</td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/video-items</code>, <code>/video-items/{videoItem}</code> (+ <code>force</code>/<code>restore</code>)</td><td>Authentifié</td></tr><tr><td><code>PUT</code></td><td><code>/video-items/youtube/channel-videos</code></td><td>Authentifié</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/video-categories</code>, <code>/video-categories/{videoCategory}</code> (+ <code>position</code>, <code>force</code>, <code>restore</code>)</td><td>Authentifié</td></tr><tr><td><code>GET</code> <code>PUT</code></td><td><code>/video-settings</code></td><td>Authentifié</td></tr></tbody></table><h2 id="publicites" tabindex="-1">Publicités <a class="header-anchor" href="#publicites" aria-label="Permalink to &quot;Publicités&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Accès</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/ads</code>, <code>/ads/{ad}</code></td><td>Public</td></tr><tr><td><code>GET</code></td><td><code>/ad-identifiers</code>, <code>/ad-identifiers/{ad_identifier}</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/ads</code>, <code>/ads/{ad}</code></td><td>Authentifié</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/ad-identifiers</code>, <code>/ad-identifiers/{ad_identifier}</code></td><td>Authentifié</td></tr></tbody></table><h2 id="newsletter" tabindex="-1">Newsletter <a class="header-anchor" href="#newsletter" aria-label="Permalink to &quot;Newsletter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Accès</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/newsletter/emails</code>, <code>/newsletter/phones</code></td><td>Public — auto-inscription</td></tr><tr><td><code>GET</code> <code>PUT</code> <code>DELETE</code></td><td><code>/newsletter/emails</code>, <code>/newsletter/phones</code> (+ <code>/{id}</code>)</td><td>Authentifié</td></tr><tr><td><code>GET</code> <code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/newsletter/campaigns</code> (+ <code>/{campaign}</code>)</td><td>Authentifié</td></tr></tbody></table><h2 id="utilisateurs-roles-et-permissions" tabindex="-1">Utilisateurs, rôles et permissions <a class="header-anchor" href="#utilisateurs-roles-et-permissions" aria-label="Permalink to &quot;Utilisateurs, rôles et permissions&quot;">​</a></h2><p>Voir <a href="./authentication.html#roles-et-permissions">Authentification</a> pour le détail des guards et permissions nommées.</p><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Accès</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/roles</code>, <code>/permissions</code></td><td>Public</td></tr><tr><td><code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/roles</code>, <code>/permissions</code> (+ <code>/{id}</code>)</td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/roles/user/{user?}</code>, <code>/permissions/user/{user?}</code></td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/users</code>, <code>/users/{user}</code>, <code>/users/search/{query?}</code>, <code>/users/type/administrators</code></td><td>Authentifié</td></tr><tr><td><code>POST</code></td><td><code>/users</code>, <code>/users/import</code></td><td>Authentifié + permission <code>action-add-user</code></td></tr><tr><td><code>PUT</code></td><td><code>/users/{user}</code></td><td>Authentifié + permission <code>action-edit-user</code></td></tr><tr><td><code>DELETE</code></td><td><code>/users/{user}</code></td><td>Authentifié + permission <code>action-delete-user</code></td></tr><tr><td><code>PUT</code></td><td><code>/users/self/{user}</code></td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/user/permissions/{user?}</code>, <code>/user/sessions/{user?}</code>, <code>/user/devices/{user?}</code>, <code>/user/place/{user?}</code>, <code>/user/roles/{user?}</code></td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/user/email/{email}</code>, <code>/user/phone/{phone}</code>, <code>/user/username/{username}</code></td><td>Authentifié</td></tr><tr><td><code>GET</code> <code>POST</code> <code>PUT</code> <code>DELETE</code></td><td><code>/user-sessions</code>, <code>/user-devices</code>, <code>/user-place</code> (+ <code>/{id}</code>)</td><td>Authentifié</td></tr></tbody></table><h2 id="mediatheque" tabindex="-1">Médiathèque <a class="header-anchor" href="#mediatheque" aria-label="Permalink to &quot;Médiathèque&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Accès</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/media-files</code>, <code>/media-files/{mediaFile}</code>, <code>/media-files/search/{query?}</code>, <code>/media-files/list/months</code></td><td>Authentifié</td></tr><tr><td><code>POST</code></td><td><code>/media-files/list</code>, <code>/media-files/paths/list</code>, <code>/media-files/upload</code></td><td>Authentifié</td></tr><tr><td><code>POST</code></td><td><code>/media-files/replace/{mediaFile}</code>, <code>/media-files/delete</code></td><td>Authentifié</td></tr><tr><td><code>DELETE</code></td><td><code>/media-files/{mediaFile}</code> (+ <code>force</code>, <code>force/all</code>)</td><td>Authentifié</td></tr><tr><td><code>PUT</code></td><td><code>/media-files/restore/{mediaFile}</code></td><td>Authentifié</td></tr></tbody></table><p>Aucune route de la médiathèque n&#39;est publique, contrairement aux autres ressources de contenu.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Accès</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/notifications</code>, <code>/notifications/unread</code>, <code>/notifications/read</code></td><td>Authentifié</td></tr><tr><td><code>PUT</code></td><td><code>/notifications/mark/{notification}</code>, <code>/notifications/mark-all</code></td><td>Authentifié</td></tr><tr><td><code>DELETE</code></td><td><code>/notifications/{notification}</code></td><td>Authentifié</td></tr></tbody></table><h2 id="statistiques" tabindex="-1">Statistiques <a class="header-anchor" href="#statistiques" aria-label="Permalink to &quot;Statistiques&quot;">​</a></h2><p>Toutes authentifiées — alimentent la <a href="./../admin-panel/content-management/getting-started.html">Vue d&#39;ensemble</a> de l&#39;administration.</p><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/visits</code>, <code>/visitors</code></td></tr><tr><td><code>GET</code></td><td><code>/count/users</code>, <code>/count/administrators</code>, <code>/count/others</code></td></tr><tr><td><code>GET</code></td><td><code>/count/news-articles</code> (+ <code>/status/{status}</code>, <code>/author/{id}</code>), <code>/count/news-categories</code>, <code>/count/news-comments</code>, <code>/count/news-tags</code></td></tr><tr><td><code>GET</code></td><td><code>/count/media-files</code> (+ <code>/type/{type}</code>, <code>/trashed</code>)</td></tr></tbody></table><h2 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h2><p>Voir <a href="./../plugins-development/basics.html#lister-installer-et-gerer-les-plugins">Développement de plugins</a> pour le détail du cycle de vie.</p><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Accès</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/plugins</code>, <code>/plugins/{id}</code></td><td>Public</td></tr><tr><td><code>POST</code></td><td><code>/plugins/install</code></td><td>Authentifié</td></tr><tr><td><code>PUT</code></td><td><code>/plugins/{id}/update</code>, <code>/plugins/{id}/enable</code>, <code>/plugins/{id}/disable</code></td><td>Authentifié</td></tr><tr><td><code>DELETE</code></td><td><code>/plugins/{id}/uninstall</code></td><td>Authentifié</td></tr></tbody></table><h2 id="divers" tabindex="-1">Divers <a class="header-anchor" href="#divers" aria-label="Permalink to &quot;Divers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Description</th><th>Accès</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/email</code></td><td>Envoi d&#39;un email via le driver de mail configuré.</td><td>Authentifié</td></tr><tr><td><code>POST</code></td><td><code>/sms</code></td><td>Envoi d&#39;un SMS via le fournisseur configuré.</td><td>Authentifié</td></tr><tr><td><code>POST</code></td><td><code>/file/upload</code>, <code>/file/replace</code>, <code>/file/delete</code>, <code>/file/download</code>, <code>/file/check</code></td><td>Upload/gestion de fichiers génériques (hors médiathèque).</td><td>Authentifié</td></tr><tr><td><code>GET</code></td><td><code>/translations/{locale}</code></td><td>Chaînes de traduction de l&#39;interface pour une langue donnée.</td><td>Public</td></tr><tr><td><code>GET</code> <code>PUT</code></td><td><code>/app-settings</code>, <code>/app-information</code></td><td>Réglages globaux et <a href="./../admin-panel/content-management/platform-identity.html">informations de base</a> de la plateforme.</td><td>Public</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>app-settings</code>/<code>app-information</code> ne sont pas protégées par <code>auth:sanctum</code> au niveau de la route — à garder en tête si l&#39;un ou l&#39;autre est étendu.</p></div><h2 id="installation-serveur" tabindex="-1">Installation &amp; serveur <a class="header-anchor" href="#installation-serveur" aria-label="Permalink to &quot;Installation &amp; serveur&quot;">​</a></h2><p>Ces routes servent principalement l&#39;assistant d&#39;installation web (voir <a href="./../getting-started/installation.html">Installation</a>) plutôt qu&#39;une intégration externe classique.</p><table tabindex="0"><thead><tr><th>Méthode</th><th>Route</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/</code></td><td>Vérification de l&#39;état du serveur.</td></tr><tr><td><code>POST</code></td><td><code>/server/configure</code></td><td>Configuration initiale du serveur (URL, etc.).</td></tr><tr><td><code>GET</code> <code>POST</code></td><td><code>/database</code> (+ <code>/test</code>, <code>/create</code>, <code>/migrate</code>, <code>/seed</code>)</td><td>Connexion, création et migration de la base pendant l&#39;installation.</td></tr><tr><td><code>POST</code></td><td><code>/install/finalize</code>, <code>/install/create-admin</code></td><td>Finalisation de l&#39;installation, création du premier compte administrateur.</td></tr></tbody></table>`,46)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
